OUT=Path(__file__).resolve().parents[1]/'output/reading-writing-lessons'
GUIDES=[
dict(n=1,title='Text as Connected Discourse',codes='EN11/12RWS-IIIa-1 and EN11/12RWS-IIIa-2',
description='Understand connected discourse and organize information using brainstorming, graphic organizers, and outlines.',
pages=[[
('Learning goals','Explain how sentences form a unified message; distinguish coherence from cohesion; and select an organizing technique for a specific writing purpose.'),
('From sentences to a message','A text is connected discourse when its ideas work together for a purpose and an audience. Correct sentences alone do not guarantee a meaningful text. Each sentence should contribute to the central idea, and readers should be able to follow the relationships between ideas. A notice, explanation, report, and argument organize information differently because they help readers do different things.'),
('Coherence and cohesion','Coherence concerns the logical relationship among ideas. A paragraph about preparing for a laboratory visit becomes difficult to follow if it suddenly discusses a basketball score. Cohesion concerns the language that links sentences: pronouns, repeated key terms, synonyms, conjunctions, and transitions. A paragraph may contain many transitions but still lack coherence if its ideas do not belong together.'),
('Read and examine','“Bring a reusable water bottle on the field visit. Refill it before departure because drinking water may not be available during the journey. After the activity, empty and clean the bottle before storing it.” The passage has a shared purpose: preparing and caring for one item. “It” refers to the bottle, “because” gives a reason, and “after” establishes sequence. These links support a logical progression from preparation to care.'),
('Choose information for the reader','Before drafting, ask who will read the text, what they need to know, and what action or understanding the text should produce. Include necessary details and remove irrelevant information. If you do not know a date, price, or rule, verify it rather than inventing a detail that could mislead readers.'),
('Check your understanding','Would adding “My favorite film is a comedy” improve the water bottle notice? Explain the effect on its central purpose. Would replacing “it” with an unclear pronoun improve cohesion? Identify the noun every pronoun needs to refer to.')
],[
('Four ways to organize ideas','Brainstorming produces a list of possible ideas without committing to their final order. A graphic organizer makes relationships visible: a web groups details around one central idea, a sequence chart shows stages, and a cause and effect map connects reasons and results. A topic outline uses parallel words or phrases for main and supporting ideas. A sentence outline expresses every point as a complete sentence.'),
('Worked planning sequence','Purpose: explain how to prepare a study space. Brainstorm: lighting, water, task list, charging cable, social media alerts, chair, music, due dates. Select details relevant to preparation. A graphic organizer can group them as environment, materials, and distractions. Topic outline: I Environment; A Lighting; B Seating. II Materials; A Task list; B Required resources. III Distractions; A Notifications; B Unrelated tabs. The groups provide an order that a reader can follow.'),
('Turn an outline into sentences','Sentence outline: I A suitable environment makes the study task easier to begin. A The learner checks that the work area has adequate light. B The learner chooses a seat that supports comfortable reading. Complete-sentence points clarify what each paragraph will actually say. Keep items at the same level parallel and ensure supporting points explain the main point above them.'),
('Guided practice','Plan a short notice explaining how classmates can return borrowed classroom supplies. Produce a brainstorming list of eight ideas, group the useful ideas in an organizer, and prepare a topic outline. Use only procedures you can explain without inventing school rules. Write a 120 to 150 word notice with a clear central purpose and underline three cohesive devices.'),
('Self check','1 Identify one idea you removed and explain why it did not help the reader. 2 Convert one topic-outline point into a sentence-outline point. 3 Circle each pronoun and connect it to its referent. 4 Read the paragraphs in order and explain the relationship between each pair.'),
('Review notes','An unrelated film preference weakens coherence because it does not support the notice’s purpose. An unclear pronoun weakens cohesion because the reader cannot identify its referent. “Required resources” is a topic-outline phrase; “The learner gathers the required resources before beginning” is a sentence-outline statement. Your practice text can use different wording if its purpose, sequence, and references remain clear.')
]]),
dict(n=2,title='Patterns of Development',codes='EN11/12RWS-IIIbf-3',
description='Recognize eight patterns of development and choose supporting details that match a text’s purpose.',pages=[[
('Learning goals','Identify eight patterns of development, recognize the relationships each pattern establishes, and explain why a writer chooses a particular pattern for an audience.'),
('Patterns express relationships','A pattern of development is a way of selecting and arranging information to develop a central idea. Identify the relationship among the details rather than guessing from one signal word. A text can combine several patterns while using one as its main structure. The most effective pattern depends on what the reader needs to understand.'),
('Narration and description','Narration develops an event through a meaningful sequence: “The lights went out during rehearsal. The performers paused, and the stage manager checked the emergency lighting before practice resumed.” Description develops an impression through relevant sensory or spatial details: “A narrow aisle divides the bright room, with tall shelves along the back wall.” Narration answers what happened; description helps readers picture or experience something.'),
('Definition and exemplification or classification','Definition explains what a term means and what distinguishes it from related ideas. “A study log is a dated record of learning goals, activities, and reflections.” Exemplification makes an idea concrete through instances: “A log may record a solved practice problem or a question to revisit.” Classification groups items using a consistent basis: “Study resources can be grouped as print, audio, and interactive resources.” Do not change the basis of grouping halfway through a classification.'),
('Comparison and contrast','This pattern explains similarities and differences using comparable criteria. A print dictionary and a dictionary app can be compared by access, search method, and available features. Use a block structure, discussing one item and then the other, or a point-by-point structure, discussing both under each criterion. A fair comparison uses the same criteria for both items.'),
('Quick reading check','A paragraph begins with a term, names its broader category, and explains its distinguishing features. Which pattern is likely dominant? What additional evidence would distinguish classification from a list of unrelated items?')
],[
('Cause and effect','Cause and effect examines why something happens or what follows from it. A weak paragraph may mistake sequence for causation: two events occurring together does not prove one caused the other. Explain a plausible mechanism and qualify a claim when evidence is limited. “Repeatedly interrupting a reading session can make the argument harder to follow because the reader must reconstruct earlier points” connects a cause, process, and result.'),
('Problem and solution','Identify a specific difficulty, explain why it matters, and evaluate a response. “Borrowed tools are difficult to locate because return locations are unclear. A labeled return tray and a sign-out record could make the process easier to track.” A strong solution addresses the actual cause and acknowledges cost, feasibility, or possible limitations rather than promising that every problem will disappear.'),
('Persuasion','Persuasion seeks agreement or action through reasons and relevant evidence. State a position, support it, consider an alternative view, and explain why the requested action is reasonable. Emotional language alone cannot establish a factual claim. “A class should use reusable labels because they can be updated when storage changes” offers a reason that readers can evaluate.'),
('One idea with different purposes','Topic: a shared equipment shelf. A description locates the shelves and labels. Classification groups the equipment by function. Cause and effect explains how an unclear label may delay retrieval. Problem and solution proposes a labeling method. Persuasion argues that the class should adopt it. The topic remains the same, but the selection and order of details change with the purpose.'),
('Guided practice','Write two 100 word paragraphs about organizing a personal notebook. Use definition for the first and comparison and contrast for the second. Label the relationship each paragraph develops. Then write three sentences evaluating whether your chosen details and organization match the stated pattern. Replace any detail that does not serve the paragraph’s purpose.'),
('Self check and review','A term’s category and distinguishing features signal definition. Classification requires meaningful groups based on one consistent principle. Check that a comparison applies the same criteria to both items, that a causal explanation does more than list events, and that a solution addresses the stated problem. Different patterns are acceptable when the writer can justify their purpose and develop the relationship consistently.')
]]),
dict(n=3,title='Properties of Effective Writing',codes='EN11/12RWS-IIIgh-4',
description='Develop organization, coherence, cohesion, appropriate language, and accurate mechanics through purposeful revision.',pages=[[
('Learning goals','Recognize the properties of a well-written text; diagnose problems that affect meaning; and distinguish revision of ideas from editing and proofreading.'),
('Organization','Organization gives the text a purposeful structure. An introduction establishes the subject and direction; body paragraphs develop related ideas; a conclusion draws the discussion together. A paragraph normally develops one main point, with supporting details that explain or demonstrate it. The form should serve the reader: a procedure needs a usable sequence, while a comparison needs shared criteria.'),
('Coherence and cohesion','Coherence means ideas fit together logically. Cohesion means language makes connections visible. Readers should understand why one sentence follows another. Use repeated key terms when helpful, pronouns with clear referents, and transitions that identify real relationships. “However” should signal a contrast, not merely decorate a sentence. Too many unnecessary transitions can make writing less natural.'),
('Language use','Choose vocabulary, tone, and sentence structure appropriate to the audience and purpose. Prefer precise wording to vague expressions. “Place the signed form in the blue tray” is more useful than “Put that thing there.” Avoid unsupported absolutes such as “This method always works.” A qualified claim states the conditions or limits that matter. Maintain a respectful tone and avoid unnecessary jargon.'),
('Mechanics','Mechanics includes spelling, capitalization, punctuation, and conventions that help readers interpret the text. A sentence boundary can change meaning. A comma alone normally cannot join two independent clauses. Revise “The printer stopped, the paper tray was empty” as two sentences or use an appropriate conjunction. Also check agreement, verb consistency, and the spelling of terms that a spellchecker may not recognize.'),
('Read with a reader’s questions','What is the main point? How does each detail support it? Does a transition name the correct relationship? Is a pronoun’s referent clear? Could a reader follow the instructions without guessing? Answering these questions helps locate problems that proofreading alone would miss.')
],[
('Worked revision','First version: “The exhibit opens tomorrow, it is good. Visitors should go there because things are there. Bring it.” Revised version: “The class exhibit opens tomorrow in the activity room. Visitors can examine the displays and read the project explanations. Bring a notebook if you want to record questions for the presenters.” The revision identifies the location, replaces vague wording, supplies a purpose for visiting, and clarifies what to bring.'),
('Explain the changes','The revised text repairs a comma splice, replaces unclear references, and connects each detail to the invitation. Adding a location develops the information; correcting a comma is editing. Both matter, but a grammatically correct sentence may still fail if it omits what a reader needs. Revision should begin with purpose and meaning before focusing on small surface errors.'),
('A practical revision sequence','First, identify the purpose, audience, and central message. Second, check the order and relevance of main ideas. Third, develop missing support and remove repetition. Fourth, improve transitions and references. Fifth, edit language and sentence structure. Finally, proofread the completed text for spelling, punctuation, and formatting. Read aloud or pause before the final check so familiar errors are easier to notice.'),
('Guided practice','Revise this paragraph into a clear 100 to 130 word explanation: “A reading journal is nice, people write. First finish it before reading. A quote is there and they explain it. Everyone understand a book immediately. The journal help because it is good.” Establish a purpose, reorder the process, explain what an entry contains, and replace the unsupported absolute. Keep a log of four changes and classify each as development, organization, language, or mechanics.'),
('Self check','Your revision should place reading before a response, explain the link between a quotation and a reflection, and avoid claiming that all readers understand immediately. Check agreement in “everyone understands” and “the journal helps.” A useful journal entry identifies the passage, records a response, and explains a question or insight. Many final paragraphs can meet these criteria; the reasoning behind your changes matters.'),
('Before you finish','Check the text once for ideas and once for mechanics. Do not replace a specific, accurate sentence with an impressive sounding sentence that is harder to understand. Effective writing helps the intended reader follow a purposeful message.')
]]),
dict(n=4,title='Critical Reading and Claims',codes='EN11/12RWS-IIIij-5, EN11/12RWS-IIIij-6 and EN11/12RWS-IVac-7',
description='Distinguish explicit and implicit claims, evaluate fact, value, and policy claims, and examine a text’s context.',pages=[[
('Learning goals','Identify what a writer states and implies, distinguish three types of claims, and explain how purpose, audience, and connections with other texts shape interpretation.'),
('Read for ways of thinking','Critical reading examines how an author builds meaning. Ask what the writer wants readers to accept, how the message is supported, and which assumptions are left unstated. Critical reading is not automatic disagreement: a careful reader can recognize a strength while identifying a limitation. Separate what the passage actually says from an inference you bring to it.'),
('Explicit and implicit claims','An explicit claim appears directly in the text. “The class should adopt a rotating equipment monitor” clearly recommends an action. An implicit claim is suggested rather than directly stated. If a notice describes shared equipment as “everyone’s responsibility,” it may imply that learners should help care for it. An interpretation of an implicit claim must be supported by wording or context; it is not permission to invent the writer’s beliefs.'),
('Claims of fact','A claim of fact asserts that something is true, happened, or has a particular relationship. It can be investigated using appropriate evidence. “The reading room opens at eight” is a factual claim, but its truth still needs verification through the current schedule. A factual form does not turn a statement into an established fact. Look for evidence that is relevant, current, and traceable.'),
('Claims of value and policy','A value claim evaluates something using a standard: “A clear explanation is more useful than a long explanation.” Ask what “useful” means and why that standard matters. A policy claim proposes what should be done: “The class should post a return checklist.” Ask whether the action addresses the stated need, whether it is feasible, and what consequences or alternatives require attention.'),
('Practice distinction','“The cabinet contains three labeled shelves” is a claim of fact. “This is the fairest borrowing procedure” is a value claim that needs a standard for fairness. “A borrower should record the return date” is a policy claim. One sentence can combine types, so explain the function of the particular claim you identify.')
],[
('Context matters','Context includes the writer, audience, purpose, situation, publication setting, and relevant background. A request addressed to a coordinator may use different support from a poster addressed to learners. A publication date can matter when a text describes a changing schedule or policy. Check authorship and source before relying on a screenshot or an isolated quotation.'),
('Intertext and hypertext','Intertext concerns a text’s relationship with other texts, such as a proposal that quotes a policy or responds to an earlier article. Explain how the connection changes meaning rather than merely naming a second source. Hypertext uses links that let a reader move between connected information. A linked reference can help verify a claim, but the presence of a link alone does not establish credibility.'),
('Practice passage','“The class should keep a shared supply log. The log will solve every borrowing problem. A record of borrower names and return dates makes transactions easier to trace. The most responsible classes already use logs.” Read these statements as claims to evaluate. The passage does not provide a study, an official rule, or verified observations about actual classes.'),
('Guided analysis','Identify two explicit claims and one possible assumption. Classify each explicit claim and justify your answer. Explain why “solve every borrowing problem” needs more support. What evidence would show whether a log improves tracing? What standard is used by “most responsible,” and is it established? Write a 150 word response that separates the text’s proposal from your evaluation of its evidence.'),
('Review and possible reasoning','The recommendation to keep a log is a policy claim. The promise that it will solve every problem is a factual prediction expressed too absolutely for the evidence given. The statement about responsible classes is evaluative and also suggests an unsupported comparison. A possible assumption is that users will record complete and accurate entries. A useful evaluation would consider record quality and actual borrowing outcomes rather than accepting a confident tone.'),
('Source record','When using another text, record its title, author or institution, publication date when available, URL or file name, and relevant page or paragraph. Make clear which ideas are quoted, paraphrased, inferred, or your own evaluation.')
]]),
dict(n=5,title='Assertions Counterclaims and Evidence',codes='EN11/12RWS-IVac-8, EN11/12RWS-IVac-9 and EN11/12RWS-IVac-10',
description='Formulate evaluative assertions and fair counterclaims supported by accurate, relevant, and traceable evidence.',pages=[[
('Learning goals','Explain critical reading as reasoning, formulate evaluative statements, construct a meaningful counterclaim, and select textual evidence that supports a defensible judgment.'),
('Assertions need reasons','An assertion states an interpretation or judgment that a writer asks readers to consider. An evaluative assertion judges a text’s content or properties according to an explained criterion. “The notice is unclear” is incomplete as an evaluation unless the reader knows what is unclear and why it matters. “The notice omits the collection location, so readers cannot tell where to return the forms” connects a judgment with evidence and a consequence.'),
('Claim evidence and reasoning','A claim states the point. Evidence supplies relevant support, such as a quotation, accurate paraphrase, or verifiable observation. Reasoning explains how the evidence supports the point. Quoting a sentence is not enough if the reader cannot see the connection. Textual evidence can show what an author says; it does not automatically prove that every real-world claim made by that author is true.'),
('Meaningful counterclaims','A counterclaim presents a reasonable challenge or alternative interpretation. Represent the alternative fairly before responding. “Anyone who disagrees is lazy” attacks people rather than addressing their reasons. A stronger response identifies the concern, acknowledges what is reasonable, and explains how evidence supports a limited conclusion. If an objection reveals a real weakness, revise the claim rather than pretending the weakness does not exist.'),
('Quality of evidence','Check accuracy, relevance, sufficiency, and source credibility. Accuracy means the quotation or paraphrase preserves the source’s meaning. Relevance means it bears on the particular claim. Sufficiency concerns whether the available support is enough for the strength of the conclusion. Credibility requires attention to the author’s knowledge, method, purpose, and publication context. No single checklist replaces careful reading of the source.'),
('Keep the limits visible','Words such as “may,” “in this passage,” or “under these conditions” can make an evaluation more accurate. Do not turn one example into a universal conclusion. Identify what the source allows you to conclude and what would require additional evidence.')
],[
('Worked text and evaluation','Practice text: “A task checklist can help a learner track unfinished steps. However, it must be updated when instructions change. A checklist cannot replace an explanation of a difficult concept.” Assertion: the passage gives qualified advice rather than promising that a checklist guarantees success. Evidence: it states that a checklist “cannot replace an explanation.” Reasoning: this limitation distinguishes tracking progress from understanding a concept.'),
('A fair counterclaim and response','Counterclaim: a learner might spend too much time maintaining the checklist. Response: this is a reasonable concern, so a short checklist should include only meaningful stages and be revised only when needed. The original text supports tracking and updating, but it does not establish an ideal checklist length or a measured improvement in scores. Those stronger claims would need additional evidence.'),
('Quote paraphrase and cite','Quote when the exact wording is important and use quotation marks. Paraphrase by restating the idea in your own structure while preserving its meaning. Both quotations and paraphrases need attribution. Record a page, paragraph, or section that lets a reader locate the passage. Never invent a page number, quotation, author, or reference to make support appear stronger.'),
('Build an evidence map','For each evaluative point, record five items: your assertion, the supporting passage, its source location, an explanation of the connection, and a limitation. This map helps reveal unsupported claims before drafting a critique. Organize the final critique around the main judgments rather than around a sequence of disconnected quotations.'),
('Guided practice','Using the checklist passage above, write two evaluative assertions: one about the advice and one about how the text is written. Support each with a quotation or paraphrase and reasoning. Add a fair counterclaim and a response in 150 to 200 words. Do not claim that the passage reports research results. Check that your final position is no broader than the available evidence.'),
('Review notes','One defensible judgment is that the text recognizes limits: it separates tracking steps from explaining concepts. Another is that “however” signals a qualification. A fair alternative could question whether keeping the list creates extra work. A response may propose a shorter list, but it must be presented as a reasoned suggestion, not as a proven result. Strong evaluations explain both support and uncertainty.')
]]),
dict(n=6,title='Academic and Professional Writing',codes='EN11/12RWS-IVdg-11, EN11/12RWS-IVdg-12 and EN11/12RWS-IVhj-13',
description='Plan academic texts and professional correspondence for a clear purpose, audience, and writing process.',pages=[[
('Learning goals','Distinguish the purposes and features of common academic texts and professional correspondence; choose appropriate support and organization; and use planning, drafting, revision, and editing.'),
('Begin with purpose and audience','Identify who will read the text, what the reader needs to understand or decide, and what response you seek. An academic argument develops a reasoned position; a formal request helps a recipient evaluate an action. Adjust detail, evidence, tone, and format to that purpose. Formal writing should be clear and precise rather than unnecessarily complicated.'),
('Article critique and literature review','An article critique briefly identifies the text, states an evaluative position, and examines its claims, support, and writing using evidence. A literature review synthesizes several sources around a question, theme, or disagreement. It compares findings and identifies gaps; it is more than one summary after another. Both forms distinguish the source authors’ ideas from the writer’s interpretation.'),
('Research report','A research report explains a question, method, results, and interpretation. Present what was actually done and what the evidence supports. Separate results from interpretation, document limitations, and acknowledge sources. A proposed investigation belongs in a plan or proposal, not in a report claiming that data has already been collected. Do not manufacture respondents, measurements, or findings.'),
('Project proposal','A proposal explains a need and a feasible response. It commonly identifies the rationale, objectives, beneficiaries, activities, timeline, responsibilities, resources, risks, and evaluation method. An objective should describe an observable result. Label estimates as estimates and explain their basis. Show how the proposed activities connect to the need rather than listing attractive but unrelated events.'),
('Position paper','A position paper presents a defensible stand on an issue. Establish the issue, state a focused position, support it with credible evidence and reasoning, address relevant counterarguments, and draw a justified conclusion. Consider the strongest reasonable objection. The strength of the conclusion must match the strength and scope of the support.')
],[
('Professional correspondence','A resume presents relevant qualifications, education, skills, and experience accurately. A college admission application connects the applicant’s preparation and goals to the institution’s requirements. An employment application connects relevant qualifications to the role. Office correspondence may request information, explain a procedure, document a decision, or seek approval. Follow the recipient’s stated requirements and do not invent qualifications or commitments.'),
('Parts of a formal letter','Use a date, recipient designation and address when appropriate, salutation, clear opening purpose, organized supporting details, specific requested action, respectful closing, and sender identification. A subject line can help readers identify the matter quickly. Include contact information only when needed and authorized. Keep the letter consistent with any document it accompanies.'),
('A purposeful request','“I am requesting a schedule for consulting the library catalogue during our research preparation. Our group needs to identify available references before selecting a topic. Please advise us of an appropriate consultation time and any access requirements.” The request states an action, explains its purpose, and gives the recipient a concrete way to respond. It does not assume that access or a schedule has already been approved.'),
('The writing process','Plan the purpose, audience, scope, and evidence. Draft a logical structure without treating the first wording as final. Revise missing ideas, weak support, and organization. Edit language and sentence construction. Proofread names, dates, figures, references, and formatting. Keep source notes as you work so attribution does not depend on memory at the end.'),
('Guided practice','Choose a request for permission to interview a librarian about finding references. Write a planning note identifying the recipient, purpose, needed background, and requested action. Draft a 150 to 180 word letter. Then write a short proposal outline containing an objective, activities, resources, and an evaluation method. Mark at least three revisions that improve consistency between the letter and the outline.'),
('Review notes','An appropriate objective could be to produce a documented list of relevant catalogue search strategies after an approved interview. An evaluation method could check whether the list records each strategy and its purpose. The letter should request permission and a suitable time rather than announce an unapproved appointment. If no interview has occurred, the document should not report interview findings. Accuracy and audience awareness matter across all these forms.')
]])]

styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='GuideTitle',fontName='Helvetica-Bold',fontSize=20,leading=24,spaceAfter=10,textColor=colors.black))
styles.add(ParagraphStyle(name='GuideHeading',fontName='Helvetica-Bold',fontSize=11.5,leading=15,spaceBefore=11,spaceAfter=5,textColor=colors.black))
styles.add(ParagraphStyle(name='GuideBody',fontName='Helvetica',fontSize=10.5,leading=14.5,spaceAfter=7,textColor=colors.black))
styles.add(ParagraphStyle(name='GuideSmall',fontName='Helvetica',fontSize=9,leading=12,spaceAfter=9,textColor=colors.black))
def footer(c,d):
 c.setFont('Helvetica',9);c.drawString(50,31,'Reading and Writing Skills  |  '+str(d.page));c.drawRightString(545,31,'Interface Computer College Caloocan')
OUT.mkdir(parents=True,exist_ok=True)
for g in GUIDES:
 file=OUT/f'RW_Lesson_{g["n"]:02d}.pdf';story=[]
 for i,sections in enumerate(g['pages']):
  if i:story.append(PageBreak())
  if not i:
   story.append(Paragraph(escape(g['title']),styles['GuideTitle']))
   story.append(Paragraph(f'Learning Guide  |  RW-11-12  |  Quarter {3 if g["n"]<=3 else 4}',styles['GuideSmall']))
   story.append(Paragraph('Competency alignment: '+escape(g['codes']),styles['GuideSmall']))
  else:story.append(Paragraph(escape(g['title'])+' continued',styles['GuideHeading']))
  for heading,body in sections:
   story.append(KeepTogether([Paragraph(escape(heading),styles['GuideHeading']),Paragraph(escape(body),styles['GuideBody'])]))
  if i==1:story.append(Paragraph('Curriculum reference: DepEd K to 12 Senior High School Reading and Writing Skills Curriculum Guide. https://lrmds.deped.gov.ph/detail/14520',styles['GuideSmall']))
 SimpleDocTemplate(str(file),pagesize=(595.28,841.89),rightMargin=50,leftMargin=50,topMargin=40,bottomMargin=53,title=g['title']+' Learning Guide',author='Stanley Vargas Garcia').build(story,onFirstPage=footer,onLaterPages=footer)
 g['fileName']=file.name;g['id']=f'CORE-112-RW-T{g["n"]:02d}-M01'
 print(file.name,len(PdfReader(file).pages),'pages')
(OUT/'lesson-manifest.json').write_text(json.dumps([{k:v for k,v in g.items() if k!='pages'} for g in GUIDES],indent=2),encoding='utf-8')
